<?php namespace App\Notifications; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Notification; class KebersihanKamarNotification extends Notification { use Queueable; public $kamar; public $status; public function __construct($kamar, $status) { $this->kamar = $kamar; $this->status = $status; } public function via($notifiable) { return ['database']; } public function toArray($notifiable) { $title = $this->status == 'kotor' ? 'Kamar Perlu Dibersihkan' : 'Kamar Sudah Bersih'; $msg = $this->status == 'kotor' ? 'Kamar ' . $this->kamar->nomor_kamar . ' perlu dibersihkan segera.' : 'Kamar ' . $this->kamar->nomor_kamar . ' telah dibersihkan.'; return [ 'type' => 'kebersihan', 'title' => $title, 'message' => $msg, 'url' => route('admin.kamar') ]; } }